445.     private static string ComputeHash(AuditEntry entry)
446.     {
447.         var withoutHash = entry with { Hash = null };
448.         var document = JsonDocument.Parse(JsonSerializer.Serialize(withoutHash, JsonOptions));
449.         var canonical = Canonicalize(document.RootElement);
450.         using var sha = SHA256.Create();
451.         var bytes = sha.ComputeHash(Encoding.UTF8.GetBytes(canonical));
452.         return Convert.ToHexString(bytes).ToLowerInvariant();
453.     }
