455.     private static string Canonicalize(JsonElement element)
456.     {
457.         return element.ValueKind switch
458.         {
459.             JsonValueKind.Object => "{" + string.Join(",", element.EnumerateObject().OrderBy(pair => pair.Name, StringComparer.Ordinal).Select(pair => JsonEncodedText.Encode(pair.Name) + ":" + Canonicalize(pair.Value))) + "}",
460.             JsonValueKind.Array => "[" + string.Join(",", element.EnumerateArray().Select(Canonicalize)) + "]",
461.             JsonValueKind.String => JsonSerializer.Serialize(element.GetString()),
462.             JsonValueKind.Number => element.GetRawText(),
463.             JsonValueKind.True => "true",
464.             JsonValueKind.False => "false",
465.             JsonValueKind.Null => "null",
466.             _ => "null"
467.         };
468.     }
