470.     private static string SanitizeText(string? value)
471.     {
472.         if (string.IsNullOrWhiteSpace(value))
473.         {
474.             return string.Empty;
475.         }
476. 
477.         var sanitized = value;
478.         sanitized = Regex.Replace(sanitized, @"(?i)\b(?:acc|account|acct)[A-Za-z0-9-]*\b", "[ACCOUNT_REDACTED]");
479.         sanitized = Regex.Replace(sanitized, @"(?i)\b(?:trade|instrument|security)[A-Za-z0-9-]*\b", "[REFERENCE_REDACTED]");
480.         sanitized = Regex.Replace(sanitized, @"(?<![\d])\b\d{1,3}(?:,\d{3})*(?:\.\d+)?\b(?![\d])", "[AMOUNT_REDACTED]");
481.         sanitized = Regex.Replace(sanitized, @"(?i)\b[A-Z]{2,}\d+[A-Z0-9-]*\b", "[ACCOUNT_REDACTED]");
482.         return sanitized.Trim();
483.     }
